"""v0.4.1 browser acceptance with original synthetic data, Chromium/WebKit.
WebKit on Linux is engine testing, never physical iPad/Safari acceptance.
"""
import os,shutil,json,uuid
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1];BASE='http://127.0.0.1:8092';ENGINE=os.getenv('CAFCC_BROWSER_ENGINE','chromium')
def login(page,user):
 page.goto(BASE+'/wp-login.php',wait_until='networkidle');page.locator('#user_login').fill(user);page.locator('#user_pass').fill('cafcc-disposable-only');page.locator('#wp-submit').click();page.wait_for_load_state('networkidle')
def ready(page):page.wait_for_function("document.querySelector('[data-cafcc-explorer]')&&!document.querySelector('[data-cafcc-explorer]').hasAttribute('aria-busy')")
def contrast(page,selector):
 return page.locator(selector).first.evaluate('''e=>{const s=getComputedStyle(e);const rgb=t=>t.match(/[\\d.]+/g).slice(0,3).map(Number).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4});const lum=t=>{const v=rgb(t);return v[0]*.2126+v[1]*.7152+v[2]*.0722};const a=lum(s.color),b=lum(s.backgroundColor);return {ratio:(Math.max(a,b)+.05)/(Math.min(a,b)+.05),color:s.color,fill:s.webkitTextFillColor,background:s.backgroundColor}}''')
with sync_playwright() as p:
 launch={'headless':True}
 if ENGINE=='chromium':launch.update(args=['--no-sandbox','--disable-dev-shm-usage'],**({'executable_path':shutil.which('chromium')} if shutil.which('chromium') else {}))
 browser=getattr(p,ENGINE).launch(**launch);context=browser.new_context(viewport={'width':1024,'height':1366},color_scheme='dark',reduced_motion='reduce');page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));login(page,'student_a');page.goto(BASE+'/?cafcc_view=explorer',wait_until='networkidle');ready(page)
 expect(page.locator('.cc-portal')).to_have_attribute('data-cc-theme','dark');expect(page.get_by_role('button',name='Switch to light mode')).to_have_attribute('aria-pressed','true')
 # Simulate a hostile theme, with browser-native controls and selected values.
 page.add_style_tag(content='select,option,input{color:white!important;-webkit-text-fill-color:white!important;background:white!important}')
 for selector in ['[data-filter=subject_id]','[data-filter=topic_id]','.cc-concept-input']:
  c=contrast(page,selector);assert c['ratio']>=4.5,c;assert c['color']==c['fill'],c
 page.locator('[data-filter=subject_id]').evaluate('e=>e.disabled=true');assert contrast(page,'[data-filter=subject_id]')['ratio']>=4.5;page.locator('[data-filter=subject_id]').evaluate('e=>e.disabled=false')
 for concept in ['Ind AS 109','Embedded Derivatives','Ind AS 115','Securitisation']:
  page.locator('.cc-concept-input').fill('TEST NAV '+concept);target=page.locator('#cc-concept-results button').filter(has_text='TEST NAV '+concept).first;expect(target).to_be_visible();expect(target).to_contain_text('No verified questions yet');target.click();ready(page);expect(page.locator('[data-filter=chapter_id]')).not_to_have_value('');expect(page.locator('.cc-question-list')).to_contain_text('No verified questions available yet');page.get_by_role('button',name='Clear All',exact=True).click();ready(page)
 for width in [390,768,1024]:
  page.set_viewport_size({'width':width,'height':1000});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth'),width
 page.set_viewport_size({'width':1024,'height':1366});page.screenshot(path=str(ROOT/f'docs/previews/v041-{ENGINE}-dark-syllabus.png'),full_page=True)
 page.get_by_role('button',name='Switch to light mode').click();expect(page.locator('.cc-portal')).to_have_attribute('data-cc-theme','light');assert contrast(page,'[data-filter=subject_id]')['ratio']>=4.5
 page.goto(BASE+'/?cafcc_view=dashboard',wait_until='networkidle');expect(page.locator('[data-cafcc-dashboard]')).to_be_visible();assert not page.locator('[data-cafcc-explorer]').count();expect(page.locator('.cc-portal')).to_have_attribute('data-cc-theme','light');page.screenshot(path=str(ROOT/f'docs/previews/v041-{ENGINE}-dashboard.png'),full_page=True)
 page.goto(BASE+'/?cafcc_view=practice',wait_until='networkidle');ready(page);expect(page.locator('[data-view=practice]')).to_be_visible();page.locator('[data-filter=personal]').select_option('bookmarks');ready(page);expect(page.locator('.cc-question')).to_have_count(1);expect(page.locator('.cc-official-citation')).to_contain_text('Independently authored example');page.locator('[data-filter=personal]').select_option('needs_revision');ready(page);expect(page.locator('.cc-question')).to_have_count(1);page.screenshot(path=str(ROOT/f'docs/previews/v041-{ENGINE}-my-practice.png'),full_page=True)
 bcontext=browser.new_context(viewport={'width':390,'height':844});b=bcontext.new_page();login(b,'student_b');b.goto(BASE+'/?cafcc_view=practice',wait_until='networkidle');ready(b);b.locator('[data-filter=personal]').select_option('bookmarks');ready(b);expect(b.locator('.cc-question')).to_have_count(0)
 admin=browser.new_page();login(admin,'test_admin');admin.goto(BASE+'/wp-admin/admin.php?page=cafcc-diagnostics',wait_until='networkidle');expect(admin.get_by_role('heading',name='Next required action',exact=True)).to_be_visible();expect(admin.locator('body')).to_contain_text('Installing the plugin does not import') if 'Installing the plugin does not import' in admin.locator('body').inner_text() else expect(admin.locator('body')).to_contain_text('Processing a PDF does not write to WordPress');assert not admin.locator('.cc-theme-toggle').count();admin.screenshot(path=str(ROOT/f'docs/previews/v041-{ENGINE}-diagnostics.png'),full_page=True)
 # Actual administrator JSON file upload -> validation -> explicit draft import.
 admin.goto(BASE+'/wp-admin/admin.php?page=cafcc-studio',wait_until='networkidle');sid='TEST-BROWSER-IMPORT-'+uuid.uuid4().hex[:10];payload=dict(batch_key=sid,records=[dict(stable_id=sid,source_hash='e'*64,source_key=sid,subject_code='FR',source_type='other',exam_attempt='TEST ONLY, no examination',section='original_browser_fixture',reference=sid,official_url='https://www.icai.org/test-original-fixture',rights_mode='reference_only',rights_basis='Original synthetic reference-only test fixture. No ICAI question prose.')]);admin.locator('#studio-import').set_input_files(dict(name='original-test-drafts.json',mimeType='application/json',buffer=json.dumps(payload).encode()));expect(admin.locator('#studio-upload-preview')).to_be_visible();apply=admin.get_by_role('button',name='Apply validated decisions / draft batch',exact=True);expect(apply).to_be_enabled();apply.click();expect(admin.locator('#studio-upload-preview')).not_to_be_visible();admin.locator('#studio-search').fill(sid);expect(admin.locator('#studio-rows tr')).to_have_count(1);expect(admin.locator('#studio-rows')).to_contain_text('needs_review');expect(admin.locator('#studio-rows')).to_contain_text('draft')
 assert not errors,errors;browser.close()
print(ENGINE+' v0.4.1 passed: reviewed empty-path/alias browsing, direct navigation, contrast under hostile theme (including disabled controls), persistent light/dark/system mode, independent Dashboard/My Practice, two-student bookmarks, diagnostics and responsive widths. Not a physical Safari/iPad test.')
